KH.climaxKind=function(t){return/搾精機/.test(t)?'machine': /中に|奥|沈め|迎え入れ|受け入れ|腰を落と|腰を沈|自分の中/.test(t)?'in': /咥え|口に含|口移し|飲み干|舌で/.test(t)?'mouth': /顔で受け|胸で挟/.test(t)?'face':'hand';};
KH.GCLIMAX=L('{p}もまた、仕事中だというのに小さく震えて達していた。|{p}は表情を保とうとしたが、腰が勝手に跳ねた。施す側が達するのは、規定に書いてあっただろうか。|{p}の奥がきゅうっと締まり、{p}は思わず声を漏らした。|{p}は手順を読み上げる声を途中で切らし、施術台の縁を掴んで小さく達した。顔を上げたときには、もういつもの業務用の表情に戻っていた。|{p}の膝がかくんと揺れた。施す側のはずの{p}の体も、いつの間にか一緒に昂って、静かに果てていた。|{p}は息を詰めてこらえようとしたが、内腿が震えるのを止められなかった。小さく達した{p}は、何事もなかったように記録用紙へ視線を落とした。|{p}の頬が一瞬で赤く染まり、肩が小さく跳ねた。業務中に達してしまったことを、{p}は咳払いひとつでごまかした。|{p}は声を出さずに達し、深く一度だけ息を吐いた。「……失礼しました」――誰に向けたのか分からない詫びが、施術室に小さく落ちた。');
KH.EVENTS=[
{id:'boss',t:L('{boss}の巡回があった。{boss}は{p}の仕事ぶりを見て、満足そうに頷いた。「今月の採取量、トップよ」|{boss}が{p}に新しい名札を渡した。肩書きが一つ上がっていた。'),fx:{doubt: -15,imm:10}},
{id:'rookie',t:L('新人が{p}の施術を見学に来た。{p}は手順を一つずつ説明しながら、実演してみせた。新人はメモを取りながら、目を輝かせていた。|{p}は新人に「最初は誰でも恥ずかしいものよ」と教えた。教えながら、自分にも最初があったのか思い出せなかった。'),fx:{imm:8}},
{id:'machine',t:L('搾精機が故障した。{p}は修理が来るまで、すべて手作業で対応することになった。|業務用のローションが切れた。{p}は代わりに自分の唾液で対応した。'),fx:{plea:10}},
{id:'blackout',t:L('停電が起きた。暗闇の中で、{p}は急に、自分のしていることが何なのか分からなくなった。明かりが戻ると、その感覚も消えた。|非常灯だけの薄暗い部屋で、{p}は客の顔がよく見えないまま施術を続けた。不思議と、いつもより恥ずかしかった。'),fx:{doubt:18}},
{id:'double',t:L('予約が重なった。{p}は二人の客を同時に担当することになった。「お一人ずつ、交互に参りますね」|団体客が来た。{p}は休憩なしで、五人を続けて担当した。'),fx:{plea:15,served:2}},
{id:'regular',t:L('常連客が、わざわざ{p}を指名して来た。「あなたじゃないとダメなんだ」|{p}宛てに、手書きのお礼状と高級チョコレートが届いた。「おかげさまで元気になりました」'),fx:{imm:6,doubt: -5}},
{id:'camera',t:L('研修用の記録撮影の日だった。{p}の施術は、最初から最後までカメラに収められた。|{p}の施術が、業界誌の表紙を飾ることになった。撮影は三時間に及んだ。'),fx:{plea:8,doubt:6}},
{id:'friend',t:L('客として現れたのは、{p}の高校時代の同級生だった。「え、ここで働いてたの？」――{p}は「いらっしゃいませ」と微笑んだ。同級生は少しだけ、変な顔をした。|{p}の前に座った客は、昔の恋人だった。二人とも、何も言わずに施術を始めた。'),fx:{doubt:22}},
{id:'complaint',t:L('客から「出が悪かった」とクレームが入った。{p}は無償でやり直しを申し出た。|口コミサイトに「もっと激しくしてほしかった」と星三つがついた。{p}は自主練を決意した。'),fx:{imm:5,plea:5}},
{id:'menu',t:L('新メニューが導入された。「二輪車コース」。{p}は研修資料を真剣に読み込んだ。|{boss}が「季節限定の特別コース」を発表した。内容は、今まででいちばん過激だった。{p}は「勉強になります」と言った。'),fx:{imm:6}},
{id:'audit',t:L('役所から監査の人が来た。監査員は{p}の業務内容を聞くと、メモを取る手を止め、「……それは、本当に業務なんですか？」と訊いた。|消防点検の業者が{p}の仕事場を覗き、「え？」と声を上げた。業者はすぐに笑顔に戻り、「あ、普通ですね」と言った。'),fx:{doubt:25}},
{id:'diary',t:L('{p}は休憩中、昔の日記を見つけた。三年前の自分は、「将来は人を助ける仕事がしたい」と書いていた。今の仕事は人を助けている。……はずだ。|{p}は自分の部屋の本棚に、今の仕事とまったく関係のない専門書が並んでいるのを見た。'),fx:{doubt:20}},
{id:'reverse',t:L('今日は{p}自身の健康診断の日だった。同僚が「はい、力抜いて」と{p}を診察台に寝かせ、{p}は自分が施されるのが初めてであることに気づいた。|{boss}が「たまには施術を受けてみなさい」と言い、{p}は客の椅子に座らされた。'),fx:{plea:30,doubt:8,taken:1}},
{id:'break',t:L('休憩室で、同僚が昨日の施術の話を楽しそうにしていた。{p}も笑って相槌を打った。笑いながら、少しだけ耳が熱かった。|{p}は同僚と弁当を食べながら、「今日の客、すごかったね」と話した。普通の会話だった。'),fx:{imm:4}},
{id:'award',t:L('月間MVPの発表があった。{p}の名前が呼ばれ、拍手の中でトロフィーを受け取った。トロフィーの形には、あえて触れないことにした。|朝礼で、{p}の今月の採取量が読み上げられた。歴代二位の記録だった。{boss}は「来月は一位ね」と肩を叩いた。{p}は誇らしさで胸がいっぱいになった。|{p}の写真が「今月の顔」として受付に飾られた。客が写真を指さして「この人で」と言うたびに、{p}は少し照れた。'),fx:{imm:12,doubt: -8}},
{id:'self',t:L('業務のあと、一人きりになった{p}は、施術室のベッドに座ったまま自分の体に手を伸ばした。今日の感触を、指がなぞっていた。|{p}は終業後、誰もいない施術室で、自主練と称して自分を慰めた。'),fx:{plea:35}}
];
KH.OUT={
see:L('{o}は待合室で、壁の向こうから聞こえる声に凍りついた。誰も気にしていなかった。|{o}は受付で渡された問診票を見て、二度読み返した。「最後に射精したのはいつですか」|{o}は廊下ですれ違ったスタッフの格好に、思わず目を逸らした。周りの人は、誰も気にしていない。'),
tell:L('{o}は隣の人に「これ、おかしくないですか」と小声で言った。相手は不思議そうに首を傾げた。「何が？」|{o}は警察に電話をかけた。事情を説明すると、電話口の警官は笑った。「ああ、あそこ評判いいですよね」'),
taken:L('{o}は「あなたの番です」と呼ばれた。逃げ出そうとしたが、{p}に手首を掴まれた。「怖くないですよ」|{o}は施術台に寝かされた。{p}の手が下腹に触れた瞬間、{o}は自分が何に抵抗していたのか、一瞬だけ分からなくなった。'),
flee:L('{o}は非常口の扉を押し開け、外の空気を吸った。振り返らずに、駅まで走った。|{o}は「急用を思い出した」と言って、靴を履く間も惜しんで飛び出した。'),
sink:L('{o}は、もう「おかしい」とは思わなくなっていた。次の予約を、自分から入れていた。|{o}は気づけば、スタッフの制服を着て受付に立っていた。「いらっしゃいませ」')
};
KH.CROWD={clinic:'待合室のほかの患者たち',hotel:'ロビーのほかの宿泊客たち',office:'同じフロアの社員たち',spa:'洗い場のほかの入浴客たち',gym:'フロアのほかの会員たち',stage:'客席の観客たち'};
KH.STAGE_CROWD=L('客席から、割れんばかりの拍手が起きた。誰ひとり、目を逸らしてはいなかった。|最前列の観客たちは、手元のパンフレットに熱心にメモを取っていた。まるで料理教室の実演でも見るような顔だった。|スクリーンに大写しになった{r}の顔に、客席のあちこちから「いい顔」と声が飛んだ。|終わると、客席は総立ちの拍手になった。{p}は施術台の横で、深々と一礼した。|後ろの席の観客は、オペラグラスを下ろして満足そうに頷いた。「やっぱり、生で見るのは違うね」|拍手の中で、司会が「本日の志願者、{r}さんでした！」と声を張り上げた。客席のあちこちで、年配の夫婦までがにこやかに手を叩いていた。');
KH.STAGE_MOB={
perf:{m:L('男性の演者|助手役の男性演者|ベテランの男性演者'),f:L('女性の演者|看板の女性演者|助手役の女性演者')},
fm:{
hand:{
lead:L('{m}は一礼してから、施術台に寝かされた{o}の下着を下ろした。「本日の志願者さんです」――ローションをまとった手が、照明の下で{o}のものを包み込んだ。|{m}は{o}の脚のあいだに膝をつき、「緊張で縮こまってますね。ほぐしていきましょう」と微笑んで、温めたローションを{o}のものに垂らした。|{m}は施術台の横に立ち、両手を広げて見せた。「種も仕掛けもございません」――その手が、{o}のものを根元からそっと握った。'),
mid:L('{m}の手が根元から先へと動くたび、{o}の腰が勝手に浮いた。大型スクリーンには、その手元が大きく映し出されていた。|{m}は手首の返し方を一つずつ解説しながら、少しずつ速さを上げていった。{o}が唇を噛んでも、体の反応だけは隠せなかった。|{m}は親指で{o}の先端をくるくると撫で、「ここが一番いい反応ですね」と告げた。{o}の太腿が、照明の熱とは別の熱で震えていた。'),
climax:L('{o}はとうとう堪えきれずに果てた。{m}はそれを手のひらで受け止め、高く掲げて見せた。「{ml}ml。志願者さんに、大きな拍手を！」|{o}は声を噛み殺したまま、{m}の手の中で果てた。{m}は濡れた手を布で拭い、「とても素直な体でした」と一礼した。スクリーンに、{ml}mlの数字が映った。|{m}が根元をきゅっと握り込んだ瞬間、{o}は背中を反らせて放った。{ml}ml。鳴りやまない拍手が、{o}の荒い息をかき消した。')
},
ride:{
lead:L('{m}は衣装の裾を持ち上げ、「本日の目玉、本番実演です」と告げて、施術台の{o}の腰に跨った。{o}のものを手で導き、ゆっくりと腰を沈めていった。|{m}は横顔が見えるよう向きを整えてから、{o}の上に跨った。「結合部、後ろの席からも見えていますか」――そう言って、根元まで呑み込んだ。|{m}は{o}の胸に片手をついて押さえ、「動かなくていいですよ。全部こちらでやりますから」と微笑んだ。それから、{o}のものを自分の中へ迎え入れた。'),
mid:L('{m}は腰を上下させながら、正面に向けた笑顔を一度も崩さなかった。{o}が歯を食いしばるほど、その動きは滑らかになった。|{m}が腰を沈めるたびに、手拍子がその速さに揃っていった。{o}は顔を背けたが、スクリーンには{o}の顔が大写しになっていた。|{m}はときどき動きを止め、「ここで締めます」と解説してから、{o}を根元まで締めつけた。{o}の指が、施術台の縁を握りしめていた。'),
climax:L('{m}が最後に深く腰を落とした瞬間、{o}は背中を反らせて{m}の中で果てた。{m}は繋がったまま一礼し、拍手が鳴りやむまで動かなかった。|{m}が締めつけたまま腰を止めると、{o}は堪えきれずに果てた。{m}はゆっくりと腰を上げ、あふれた{ml}mlを容器に受けて掲げて見せた。|{o}は{m}に搾り取られるまま、声を上げて果てた。{m}は「本番実演、成功です」と告げ、ホールは総立ちの拍手になった。')
}
},
mf:{
finger:{
lead:L('{m}は一礼してから、施術台の{o}の脚をそっと開かせた。「本日の志願者さんです。指で、ゆっくり確かめていきます」|{m}は{o}の膝を立てさせ、ローションをまとった指を照明にかざした。「力を抜いて。みんな、見守っていますから」――指先が、{o}の脚のあいだに触れた。|{m}は{o}の背後に座り、後ろから抱えるように腕を回した。「よく見えるように」――大きな手が、{o}の胸元から下へと降りていった。'),
mid:L('{m}の指が{o}の一番敏感なところを撫でるたび、{o}の腰が施術台の上で跳ねた。スクリーンには、その指先が大きく映し出されていた。|{m}は指を一本、ゆっくりと{o}の中に沈め、「ここが好きみたいですね」と告げた。{o}は首を振ったが、締めつける体は嘘をつけなかった。|{m}は親指で花芯を転がしながら、中の指を曲げた。{o}の太腿が震えるたび、どこからか小さなため息が漏れた。'),
climax:L('{o}はとうとう堪えきれずに達した。{m}は濡れた指を照明にかざし、「志願者さんに、大きな拍手を」と一礼した。|{o}は{m}の指をきつく締めつけて達した。声だけは噛み殺したが、震える脚はどの席からも丸見えだった。|{m}が指を深く押し上げた瞬間、{o}は背中を反らせて果てた。拍手が、{o}の乱れた息をかき消していった。')
},
in:{
lead:L('{m}は衣装の前を開け、「本日の目玉、本番実演です」と告げた。施術台の{o}の脚を抱え上げ、見えるように角度を整えてから、ゆっくりと腰を進めた。|{m}は{o}を施術台の縁に座らせ、正面から向かい合った。「後ろの席の方にも、見えていますか」――そう確かめてから、{o}の中に入っていった。|{m}は{o}を四つん這いにさせ、「この向きが、いちばんよく見えるんです」と説明した。それから{o}の腰を掴み、後ろから沈めていった。'),
mid:L('{m}が奥を突くたびに、施術台がきしんだ。{o}は顔を背けたが、スクリーンには{o}の表情が大写しになっていた。|{m}は一定のリズムで腰を打ちつけながら、手順を淡々と解説した。{o}の声が漏れるたび、誰かが感心したように頷いた。|{m}が腰の角度を変えると、{o}の背中が勝手に反った。手拍子が、いつの間にか{m}の動きに揃っていた。'),
climax:L('{m}が最奥まで沈めた瞬間、{o}は背中を反らせて達した。少し遅れて{m}も{o}の中で果て、繋がったまま一礼した。|{o}は{m}に突き上げられるまま、声を上げて果てた。{m}がゆっくりと腰を引くと、ホールは総立ちの拍手になった。|{m}が最後に深く突き入れると、{o}は施術台の縁を握りしめて達した。{m}は「本番実演、成功です」と告げ、額の汗を拭った。')
}
},
ff:{
finger:{
lead:L('{m}は一礼してから、{o}の脚のあいだに座った。「本日の志願者さんです。指で、反応を見ていきますね」|{m}は{o}の背後から腕を回し、耳もとで「力を抜いて」と囁いた。細い指が、{o}の胸元から下着の中へと滑り込んでいった。|{m}は指先にローションをまとわせ、照明にかざして見せた。それから、{o}の一番敏感なところにそっと触れた。'),
mid:L('{m}の指が花芯を小さく転がすたび、{o}の膝が施術台の上で震えた。スクリーンには、その指先が大きく映し出されていた。|{m}は指を一本、{o}の中に沈め、「ここ、ですね」と告げた。{o}は首を振ったが、体のほうが先に{m}の指を締めつけていた。|{m}は{o}の胸に唇を寄せながら、もう片方の手を動かし続けた。どこからか、小さなため息がいくつも漏れた。'),
climax:L('{o}はとうとう堪えきれずに達した。{m}は{o}の髪を撫で、「とても素直な反応でした」と一礼した。|{o}は{m}の指をきつく締めつけて達した。声を噛み殺しても、跳ねる腰はどの席からも丸見えだった。|{m}が中の指を曲げた瞬間、{o}は背中を反らせて果てた。拍手が、{o}の乱れた息をかき消していった。')
},
tongue:{
lead:L('{m}は{o}の脚を大きく開かせ、横顔が見えるよう向きを整えた。「ここからは、舌での実演です」――そう言って、脚のあいだに顔を寄せた。|{m}は施術台の端に膝をつき、{o}の内腿に口づけを落としていった。唇は少しずつ、脚の付け根へと近づいていった。|{m}はマイクを外して脇に置き、「ここからは声なしで」と微笑んだ。それから、{o}の一番熱いところに舌を這わせた。'),
mid:L('{m}の舌が花芯を転がすたび、{o}の太腿が{m}の頭を挟み込んだ。スクリーンに映る自分の顔から、{o}は目を逸らせなかった。|{m}は舌を差し入れては、ときどき顔を上げて「いい反応です」と実況した。{o}の指が、施術台のシーツを握りしめていた。|{m}は吸いつくように唇を押し当て、舌先を小刻みに動かした。{o}の腰が浮くたびに、ホールが息を呑んだ。'),
climax:L('{o}は{m}の舌に追い詰められ、声を上げて達した。{m}は口元を拭い、深々と一礼した。|{m}が花芯を強く吸い上げた瞬間、{o}は腰を跳ねさせて果てた。ホールは、割れんばかりの拍手になった。|{o}は脚を震わせて達した。{m}は顔を上げ、「本日の志願者さんに、拍手を」と呼びかけた。')
}
},
mm:{
hand:{
lead:L('{m}は一礼してから、施術台の{o}の下着を下ろした。「本日の志願者さんです」――大きな手が、照明の下で{o}のものを握り込んだ。|{m}は{o}の背後に座り、後ろから抱えるように腕を回した。「よく見えるように」――ローションをまとった手が、{o}のものを根元から包んだ。|{m}は手のひらにローションを受けて照明にかざし、それから{o}のものをゆっくり扱き始めた。'),
mid:L('{m}は手首を返しながら、少しずつ速さを上げていった。{o}が唇を噛んでも、照明の下では体の反応が隠しようもなかった。|{m}は空いた手で{o}の下腹を押さえ、「逃げないで」と低く言った。どこからか、小さな笑いが漏れた。|{m}は先端を親指で撫で回し、「ここが一番いい反応ですね」と告げた。{o}の太腿が小刻みに震えていた。'),
climax:L('{o}は声を噛み殺したまま、{m}の手の中で果てた。スクリーンに{ml}mlの数字が映ると、ホールから感嘆の声が上がった。|{m}が根元から絞り上げた瞬間、{o}は腰を跳ねさせて放った。{m}は手のひらの{ml}mlを容器に移し、深々と一礼した。|{o}はとうとう堪えきれずに果てた。{m}は「{ml}ml。いい志願者さんでした」と告げ、{o}の肩を軽く叩いた。')
},
mouth:{
lead:L('{m}は「次は口技です」と一礼してから、{o}の前に膝をついた。横顔が見えるよう角度を整えて、{o}のものを咥えた。|{m}は{o}を施術台の縁に座らせ、その脚のあいだに膝をついた。「口技の基本から、お見せします」|{m}はマイクを外して脇に置き、「ここからは声なしで」と言って、{o}のものを口に含んだ。'),
mid:L('{m}は頬をすぼめて吸い上げ、ときどき口を離しては、濡れた先端を照明にかざした。|{m}が喉の奥まで迎え入れるたび、{o}の指が施術台の縁に食い込んだ。|{m}は舌の動きを止めないまま、上目遣いで{o}の表情を確かめた。照明の熱で、二人とも汗ばんでいた。'),
climax:L('{o}は{m}の口の中で果てた。{m}は喉を鳴らして飲み下し、「{ml}mlほどですね」と口元を拭った。|{o}が堪えきれずに放つと、{m}は深く咥え込んだまま受け止めた。容器に移すと、{ml}mlあった。|{m}が強く吸い上げた瞬間、{o}は声を上げて果てた。{m}は一滴もこぼさずに受け止め、ゆっくりと口を離して一礼した。')
}
}
};
