perFields:[{id:'role',label:'役割',auto:'おまかせ（理性的な人ほど施す側）',options:[{id:'giver',label:'施す側（改変されて働く）'},{id:'taker',label:'受ける側（客として通う）'},{id:'out',label:'正気のまま紛れ込む'}]}],
